import timeit
import statistics
import io


def setup():
    global Response, CONTENT_CHUNK_SIZE, responses_success, responses_error, RuntimeError_class

    from requests.models import Response, CONTENT_CHUNK_SIZE

    RuntimeError_class = RuntimeError

    # Create a fake raw stream that yields data normally
    class FakeRawStream:
        def __init__(self, data, chunk_size=CONTENT_CHUNK_SIZE):
            self._data = data
            self._pos = 0
            self._chunk_size = chunk_size

        def stream(self, chunk_size, decode_content=True):
            pos = 0
            while pos < len(self._data):
                end = min(pos + chunk_size, len(self._data))
                yield self._data[pos:end]
                pos = end

        def read(self, amt=None):
            if self._pos >= len(self._data):
                return b""
            if amt is None:
                chunk = self._data[self._pos:]
                self._pos = len(self._data)
            else:
                chunk = self._data[self._pos:self._pos + amt]
                self._pos += amt
            return chunk

        def close(self):
            pass

        def release_conn(self):
            pass

    # Create a fake raw stream that raises an exception partway through
    class FakeErrorRawStream:
        def __init__(self, data, fail_after_bytes=1000):
            self._data = data
            self._fail_after = fail_after_bytes
            self._yielded = 0

        def stream(self, chunk_size, decode_content=True):
            pos = 0
            while pos < len(self._data):
                if self._yielded >= self._fail_after:
                    raise IOError("Simulated stream error")
                end = min(pos + chunk_size, len(self._data))
                chunk = self._data[pos:end]
                self._yielded += len(chunk)
                yield chunk
                pos = end

        def read(self, amt=None):
            raise IOError("Simulated read error")

        def close(self):
            pass

        def release_conn(self):
            pass

    import random
    random.seed(42)

    # Prepare a set of successful responses with varying body sizes
    responses_success = []
    body_sizes = [100, 1000, 10000, 50000, 100000, 500000]
    for size in body_sizes:
        for _ in range(20):
            data = bytes(random.getrandbits(8) for _ in range(size))
            r = Response()
            r.status_code = 200
            r.headers['Content-Type'] = 'application/octet-stream'
            r.raw = FakeRawStream(data)
            r.encoding = 'utf-8'
            responses_success.append(r)

    # Prepare error responses to test the new exception-handling path
    responses_error = []
    for size in [10000, 50000, 100000]:
        for _ in range(30):
            data = bytes(random.getrandbits(8) for _ in range(size))
            r = Response()
            r.status_code = 200
            r.headers['Content-Type'] = 'application/octet-stream'
            r.raw = FakeErrorRawStream(data, fail_after_bytes=size // 3)
            r.encoding = 'utf-8'
            responses_error.append(r)


def workload():
    global responses_success, responses_error, RuntimeError_class

    # Test 1: Normal content access (the happy path through the property)
    for r in responses_success:
        _ = r.content
        # Access again to test the cached path
        _ = r.content

    # Test 2: Error path - access content that will fail, verify _content_consumed is set
    for r in responses_error:
        try:
            _ = r.content
        except (IOError, OSError):
            # After the exception, _content_consumed should be True (new behavior)
            # Attempting to access content again should raise RuntimeError
            try:
                _ = r.content
            except RuntimeError_class:
                pass
            except Exception:
                pass


runtimes = timeit.repeat(workload, number=1, repeat=10, setup=setup)

print("Mean:", statistics.mean(runtimes))
print("Std Dev:", statistics.stdev(runtimes))

